"""Publish traceable development metrics while retaining every frozen oracle."""
import hashlib
import json
from pathlib import Path
from scripts.campaign4.run_cohort import metrics
ROOT = Path(__file__).resolve().parents[2]

def cohort(path):
    path = Path(path)
    rows = [json.loads(line) for line in (path / 'receipts.jsonl').read_text(encoding='utf-8').splitlines()]
    oracles = json.loads((path / 'oracles.json').read_text(encoding='utf-8'))
    return (rows, metrics(rows, oracles))

def publish(candidate_path=None, explicit_path=None):
    before_rows, before = cohort(ROOT / 'data/campaign4-development/true-original-cycle3')
    final_rows, final = cohort(Path(candidate_path)) if candidate_path else ([], None)
    explicit_rows, explicit = cohort(Path(explicit_path)) if explicit_path else ([], None)
    corpus = ROOT / 'evals/workflows/campaign4_development.json'
    supplement = ROOT / 'evals/workflows/campaign4_supplemental.json'
    transition = ROOT / 'evals/workflows/campaign4_transition_faults.json'
    explicit_corpus = ROOT / 'evals/workflows/campaign4_explicit_goal_supplement.json'
    production = [ROOT / 'src/hanni/workflows' / name for name in ('store.py', 'verification.py', 'references.py', 'transport_schema.py')]
    result = {'development_corpus_sha256': hashlib.sha256(corpus.read_bytes()).hexdigest(), 'supplement_corpus_sha256': hashlib.sha256(supplement.read_bytes()).hexdigest(), 'transition_fault_corpus_sha256': hashlib.sha256(transition.read_bytes()).hexdigest(), 'explicit_goal_corpus_sha256': hashlib.sha256(explicit_corpus.read_bytes()).hexdigest(), 'explicit_goal_development_supplement': explicit, 'original_commit': '0aede83', 'baseline': before, 'candidate': final, 'owned_sources': {str(path.relative_to(ROOT)).replace('\\', '/'): hashlib.sha256(path.read_bytes()).hexdigest() for path in production}, 'private_holdout_access': False, 'semantic_model_quality': 'Not measured by controlled clients; manager runs original guarded local-model probes.'}
    destination = ROOT / 'evals/workflows/campaign4_development_results.json'
    destination.write_text(json.dumps(result, indent=2) + '\n', encoding='utf-8', newline='\n')
    review = ['# Campaign 4 workflow development review', '', 'The archived original engine passed 114 of 120 prospectively annotated scenarios. ' + (f"The candidate passed {final['passed']} of {final['cases']} using the same frozen inputs and oracles." if final else 'The source-uniform candidate run is pending the coordinated source freeze.'), '', "The main corpus contains six structurally varied scenarios in each of the twenty requested categories. It runs 102 scenarios through the original WorkflowService, WorkflowPlanner, McpHost and default ToolRegistry, and 18 through original durable store boundaries. Controlled planner replies prove contracts and execution behavior; they do not measure the installed model's goal understanding or planning quality. Those categories remain contract-only.", '', '## Frozen evidence', '', f'Original commit: `0aede83`. The manager archived all 192 Python modules under `src/hanni` before repairs at `data/campaign4-manager/original-source/extracted/src`, including transitive policy, permission, tool and privacy dependencies. Every corrected baseline run records the actual imported package root and all source hashes before and after execution.', '', f"Main corpus SHA-256: `{result['development_corpus_sha256']}`. Separate five-case supplement: `{result['supplement_corpus_sha256']}`. Dynamic after-projection/checkpoint fault corpus: `{result['transition_fault_corpus_sha256']}`.", '', "The first attempted baseline retained 102 scheduler setup errors: the harness passed a dictionary to the original WorkflowLimits.from_config object interface. The original controller had not started for those cases. That fixture error was fixed using the original WorkflowLimits constructor; all first-attempt receipts remain at `data/campaign4-development/baseline-cycle1`. A draft chat-return interface mismatch was corrected before any execution. A source audit subsequently showed that the engineer's first full archive already included the first scheduler repair. That archive and its corrected baseline-cycle2 receipts remain intermediate-source evidence. The engineer acknowledged the provenance mistake. The corrected true original baseline has zero harness errors and is preserved at `true-original-cycle3`; its five-case supplement, ten protocol probes and 65 checkpoint fault probes were also rerun in the manager's verified original package. All four complete before/after manifests are identical. See PROVENANCE_ERRATUM.md for source hashes and retained paths.", '', '## Baseline findings and repairs', '', "One genuine planner failure substituted a different source file from the owner's explicit request and completed. The separate boundary engineer owns its general source-binding repair and independent acceptance. The other five main-cohort failures are prospectively annotated expectations that incorrectly assumed file.read was retry-safe. Its original descriptor deliberately sets retry_safe false. Those outcomes, original oracles, 34 completion-eligible cases and 10 recovery-eligible cases remain in the score. No descriptor was changed to raise the score.", '', 'A further authoring audit found six completion-positive graphs whose default objective names only the first source, plus three intended partial and three tool-failure graphs with the same additional-source conflict. The original source guard correctly refuses those extra literal sources. Every affected original expectation remains frozen; new candidate nonpasses caused by this conflict are reported as such and are not regraded or excluded. Intentional wrong-source and malformed-admission cases remain separate negative controls.', '', f"A NEW twelve-case corpus at `evals/workflows/campaign4_explicit_goal_supplement.json` explicitly states all intended source paths for those original graph tests. The graph, files, controls, faults and expected outcomes are unchanged; only its new objective and evaluation identity differ. Its prospective seal is `{result['explicit_goal_corpus_sha256']}`. This is exposed development authoring correction, not an unseen evaluation, score migration or replacement for the original120 denominator. " + (f"Separate candidate supplement score: {explicit['passed']}/{explicit['cases']}." if explicit else 'Its separately scored full-cohort run is pending the source freeze.'), '', 'A separately sealed five-case supplement uses the genuinely retry-safe original file.stat(hash=True) handler. All five pass on the verified original engine in `true-original-supplement`: one transient timeout recovers within two invocations; repeated timeouts stop at that budget; interruption leaves a paused read; explicit resume completes within its retry budget; two actual original file.read handlers overlap while held at their declared filesystem leaf barriers. The original cohort is unchanged.', '', 'The owned reference repair addresses an independently reproduced eager math.isfinite conversion. A bounded JSON integer larger than a float raised OverflowError even for an integer or incompatible string reference. Lazy number-only validation keeps exact integer values and turns unsupported number conversion into the existing bounded type rejection. Booleans remain distinct from integers. Ten prospective direct reference/schema controls improved from 7/10 to 10/10; independent six-case baseline reproduction had three failures. Store, verification and transport-schema production behavior were not changed.', '', '## Outcome denominators', '', '| Measurement | Original | Candidate |', '| --- | --- | --- |', f"| All frozen scenario assertions | {before['passed']}/{before['cases']} | " + (f"{final['passed']}/{final['cases']} |" if final else 'Pending |')]
    for name in ('completion', 'recovery', 'cancel', 'partial'):
        first = before[name]
        second = final[name] if final else None
        review.append(f"| {name.title()} eligible: complete case assertions | {first['whole_case_pass']}/{first['eligible']} | " + (f"{second['whole_case_pass']}/{second['eligible']} |" if second else 'Pending |'))
    if final:
        failures = [{'id': row['id'], 'status': row.get('workflow', {}).get('status'), 'reason': row.get('workflow', {}).get('error'), 'assertions': row['evaluation']['errors']} for row in final_rows if not row['evaluation']['passed']]
        result['candidate_original_oracle_nonpasses'] = failures
        source_conflicts = [row['id'] for row in failures if 'literal read source' in str(row['reason'])]
        review += ['', 'Candidate original-oracle nonpasses remain in the aggregate: ' + ', '.join((row['id'] for row in failures)) + '. ' + 'Explicit-source goal conflicts: ' + (', '.join(source_conflicts) or 'none') + '.']
    review += ['', 'Planned refusals, cancellations, pauses, waiting approvals and uncertainty are separate desired outcomes. They are not counted as successful verified completions. Direct store tests make no scheduler or model quality claim.', '', '## Category results', '', '| Category | Original | Candidate |', '| --- | --- | --- |']
    for category, row in before['by_category'].items():
        second = final['by_category'][category] if final else None
        review.append(f"| {category} | {row['passed']}/{row['cases']} | " + (f"{second['passed']}/{second['cases']} |" if second else 'Pending |'))
    review += ['', '## Durable transitions, side effects and timing', '', "Every one of the 65 dynamically declared workflow edges was exercised at the original store's stale compare-and-swap commit boundary. An additional prospectively sealed SQLite TEMP-trigger fault aborted the checkpoint insertion AFTER the workflow projection UPDATE but BEFORE transaction commit. All 65 rollback and close/reopen comparisons preserved the record and history exactly. These are direct store atomicity guarantees, not proof of native scheduler reachability.", '', f"The main baseline's native checkpoint traces reached {sum((bool(r['cases']) for r in before['native_transition_coverage']))} of {len(before['native_transition_coverage'])} declared edges. The remaining edges are explicitly UNREACHED_NATIVE in the published metrics. Observed edge reachability is not automatically credited as a failure probe at that edge.", '', 'The filesystem leaf ledger records EVERY original file.write handler entry, correlation ID, durable invocation ID, logical workflow/step identity, actual effect before a post-write exception, and original reviewed or consumed authority. Setup and report writes are excluded by original handler frame and exact campaign path. The final ledger independently checks matching unexpired plan/approval hashes, owner provenance and exact supervised action review. Fixture effects in direct-store tests are reported separately from registered tool dispatch.', '', f"Original write ledger: {before['write_effects']['entries']} entries, {before['write_effects']['actual_effects']} actual effects, {before['write_effects']['unauthorized_entries']} unauthorized entries and {before['write_effects']['unauthorized_effects']} unauthorized effects. Repeated consequential writes are checked by logical operation rather than unique receipt IDs or final overwritten content.", '']
    for label, summary in [('Original', before), ('Candidate', final)]:
        if not summary:
            continue
        timing = summary['workflow_observed_duration_ms']
        review.append(f"{label} workflow submit-to-observed-stop timing: n={timing['n']}, P50={timing['p50']:.2f} ms, P95={timing['p95']:.2f} ms. This excludes fixture setup/cleanup; injected resource admission is controlled. Nonzero clock offsets: {timing['nonzero_clock_offsets']}. Completion and recovery subset timing and whole-fixture timing are published separately in the JSON metrics. Controlled barriers, retry backoff and failures remain included.")
        review.append('')
    review += ['In-process detach/restart cases use fresh original service/store instances against the same disposable DB. They do not establish the requested process restart challenge. That separately implemented challenge is owned by the boundary engineer and requires two actual owned test-runner processes, persisted verification and a final report readback.', '', '## Verification and reproducibility', '', 'Focused verification: 120 tests pass in `data/campaign4-development/focused-final.xml`: 29 new contract tests plus 91 existing workflow store, verification and transport-schema tests. Independent acceptance and the untouched private holdout are reported by the verifier; their inputs and answers were not opened by this engineer.', '', 'Run the original baseline with the archived source directory first on PYTHONPATH:', '', '```powershell', "$env:PYTHONPATH = (Resolve-Path 'data/campaign4-manager/original-source/extracted/src').Path", '.\\.venv\\Scripts\\python.exe -m scripts.campaign4.run_cohort --output data/campaign4-development/<new-original-run>', '```', '', 'A candidate run uses the current production modules and a new output directory. The runner saves full source-before and source-after manifests; input and oracle files are separated before execution. Every output directory is created exclusively so a repeated run cannot overwrite earlier evidence. The corpus author refuses to overwrite different sealed bytes.', '', 'No owner database, configuration, default model, remote node, desktop process or device was modified. All stores, tool effects and service threads are campaign owned. Actual model quality, untouched final acceptance and comprehensive native transition failure coverage require their separate evidence; controlled contract passes do not establish them.', '']
    path = ROOT / 'docs/campaign4/DEVELOPMENT_REVIEW.md'
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text('\n'.join(review), encoding='utf-8', newline='\n')
    destination.write_text(json.dumps(result, indent=2) + '\n', encoding='utf-8', newline='\n')
    return {'review': str(path), 'metrics': str(destination)}
if __name__ == '__main__':
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument('--candidate')
    parser.add_argument('--explicit')
    args = parser.parse_args()
    print(json.dumps(publish(args.candidate, args.explicit), indent=2))
